// Every mutation goes through the API; client totals are only a preview.
$('#orderForm').onsubmit=async e=>{e.preventDefault();if(!currentUser||currentUser.role!=='vendor'){toast('Only vendor accounts can place orders.');return}const button=$('#orderForm .primary');button.disabled=true;try{const result=await api('/orders',{method:'POST',body:JSON.stringify({productId:selected.id,qty:Number($('#qty').value),fulfilment:$('#fulfilment').value})});orders.unshift(result.order);$('#orderDialog').close();renderOrders();await refreshMarket();toast('Order saved. View it in My orders.')}catch(error){toast(error.message);try{await refreshMarket();if(selected){$('#qty').max=Math.min(100000,selected.stock);updateTotal()}}catch{}}finally{button.disabled=false}};
$('#orderList').onclick=async e=>{const button=e.target.closest('[data-receive]');if(!button)return;button.disabled=true;try{await api(`/orders/${button.dataset.receive}/receive`,{method:'POST',body:'{}'});await refreshOrders();toast('Marked received. You can now leave a rating.')}catch(error){toast(error.message);button.disabled=false}};
$('#orderList').onchange=async e=>{const control=e.target;if(!control.dataset.review||!control.value)return;control.disabled=true;try{await api(`/orders/${control.dataset.review}/review`,{method:'POST',body:JSON.stringify({rating:Number(control.value)})});await Promise.all([refreshOrders(),refreshMarket()]);toast('Your review was saved.')}catch(error){toast(error.message);control.disabled=false}};
$('#inventory').onchange=async e=>{const control=e.target,id=control.dataset.price||control.dataset.stock||control.dataset.weight||control.dataset.handling;if(!id)return;if(!control.checkValidity()){control.reportValidity();return}control.disabled=true;try{const key=control.dataset.price?'price':control.dataset.stock?'stock':control.dataset.weight?'transportWeightKg':'transportType';const result=await api(`/products/${id}`,{method:'PATCH',body:JSON.stringify({[key]:key==='transportType'?control.value:Number(control.value)})});products=result.products;render();inventory();toast('Inventory updated.')}catch(error){toast(error.message);inventory()}finally{control.disabled=false}};
document.querySelectorAll('[data-page]').forEach(button=>{const show=button.onclick;button.onclick=()=>{show();if(!currentUser)return;const refresh=button.dataset.page==='orders'?refreshOrders():refreshMarket();refresh.catch(error=>toast(error.message))}});
$('#newProductCategory').innerHTML=productCategories.map(([name])=>`<option value="${safe(name)}">${safe(name)}</option>`).join('');
function resetTransportInputs(){const defaults=transportDefaults($('#newProductCategory').value,$('#newProductUnit').value);$('#newProductWeight').value=defaults.transportWeightKg;$('#newProductHandling').value=defaults.transportType}
$('#newProductCategory').onchange=resetTransportInputs;$('#newProductUnit').onchange=resetTransportInputs;resetTransportInputs();
$('#addProductForm').onsubmit=async e=>{e.preventDefault();const button=$('#addProductSubmit');button.disabled=true;$('#addProductError').textContent='';try{await api('/products',{method:'POST',body:JSON.stringify({name:$('#newProductName').value.trim(),category:$('#newProductCategory').value,unit:$('#newProductUnit').value,price:Number($('#newProductPrice').value),stock:Number($('#newProductStock').value),keywords:$('#newProductKeywords').value.trim(),transportWeightKg:Number($('#newProductWeight').value),transportType:$('#newProductHandling').value})});$('#addProductForm').reset();resetTransportInputs();await refreshMarket();toast('Product added. Vendors can now order it.');$('#newProductName').focus()}catch(error){$('#addProductError').textContent=error.message;translateUI()}finally{button.disabled=false}};

